/**
 * Reads the generated Semantic V2 storage catalog.
 *
 * The artifact is generated by `make generate-schemas` and validated at synth so malformed
 * contract output cannot become a Glue table with undefined columns.
 */

import * as fs from 'node:fs';

/** The Iceberg types the schema generator emits. Anything else is unhandled, not defaulted. */
const KNOWN_TYPES = [
  'boolean',
  'int',
  'bigint',
  'double',
  'decimal(38,4)',
  'date',
  'timestamp',
  'string',
] as const;

const KINDS = ['fact', 'dimension'] as const;
const LOADS = ['scd2_merge', 'partition_overwrite'] as const;

export type ColumnType = (typeof KNOWN_TYPES)[number];
export type TableKind = (typeof KINDS)[number];
export type LoadMode = (typeof LOADS)[number];

export interface GeneratedColumn {
  /** Immutable physical Iceberg identity. Must equal Glue's 1-based ordinal. */
  readonly fieldId: number;
  readonly name: string;
  readonly type: ColumnType;
  /** False when every contract writing this table writes this column. */
  readonly nullable: boolean;
  /** Where the value came from, carried into the Iceberg field doc. */
  readonly comment: string;
  /** Which of the four meanings of null applies, when the column is nullable. */
  readonly nullMeaning?: string;
}

export interface GeneratedTable {
  readonly name: string;
  readonly kind: TableKind;
  readonly load: LoadMode;
  /** The canonical columns one row is unique on. Stated by the contract, never inferred. */
  readonly grain: readonly string[];
  readonly partitionKeys: readonly string[];
  readonly measurementBases: readonly string[];
  /** Source-contract contributors during migration; not canonical mutation authority. */
  readonly writtenBy: readonly string[];
  /** The sole Semantic V2 component authorized to make this dataset current. */
  readonly canonicalPublisher: string;
  readonly columns: readonly GeneratedColumn[];
}

export interface GeneratedV2Storage {
  readonly version: number;
  readonly sourceAlignedPrefix: string;
  readonly canonicalCandidatePrefix: string;
  readonly canonicalCurrentPrefix: string;
  readonly sourceAlignedTables: readonly GeneratedTable[];
  readonly canonicalCandidateTables: readonly GeneratedTable[];
  readonly canonicalCurrentTables: readonly GeneratedTable[];
}

/** A generated schema that cannot be turned into a catalog. */
export class GeneratedSchemaError extends Error {}

function fail(problems: readonly string[], artifact: string): never {
  throw new GeneratedSchemaError(
    `${artifact} cannot be used to build the catalog:\n` +
      problems.map((problem) => `  - ${problem}`).join('\n') +
      `\nRegenerate it with \`make generate-schemas\`. If the problem is in a contract, ` +
      `\`make validate-contracts\` should have named it first.`,
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function stringArray(value: unknown): readonly string[] | undefined {
  return Array.isArray(value) && value.every((item) => typeof item === 'string')
    ? (value as string[])
    : undefined;
}

/**
 * Validates one column, collecting problems rather than throwing at the first.
 *
 * Every problem at once, the same as `getConfig` and the contract gate. Finding the
 * next malformed column on the next synth turns one correction into an afternoon.
 */
function readColumn(raw: unknown, where: string, problems: string[]): GeneratedColumn | undefined {
  if (!isRecord(raw)) {
    problems.push(`${where} is not an object`);
    return undefined;
  }
  const { fieldId, name, type, nullable, comment, nullMeaning } = raw;
  if (!Number.isInteger(fieldId) || (fieldId as number) < 1) {
    problems.push(`${where} has no positive integer fieldId`);
    return undefined;
  }
  if (typeof name !== 'string' || name === '') {
    problems.push(`${where} has no name`);
    return undefined;
  }
  if (typeof type !== 'string' || !(KNOWN_TYPES as readonly string[]).includes(type)) {
    // Loud rather than falling back to string, for the same reason the Python side has no
    // default in AMC_TYPE_MAP: a type nobody mapped is a type nobody thought about, and
    // storing a decimal as text reconciles until someone sums it.
    problems.push(
      `${where}.${name} has type ${JSON.stringify(type)}, which is not one of ` +
        `${KNOWN_TYPES.join(', ')}`,
    );
    return undefined;
  }
  if (typeof nullable !== 'boolean') {
    problems.push(`${where}.${name} has no nullable flag`);
    return undefined;
  }
  return {
    fieldId: fieldId as number,
    name,
    type: type as ColumnType,
    nullable,
    // Preserve the deployed Glue field-doc encoding. OpenTableFormatInput treats a doc-only
    // change as a table update that may replace live Iceberg metadata.
    comment: typeof comment === 'string' ? comment.replaceAll(' · ', ' ? ') : '',
    ...(typeof nullMeaning === 'string' ? { nullMeaning } : {}),
  };
}

function readTable(
  raw: unknown,
  index: number,
  problems: string[],
  area = 'tables',
): GeneratedTable | undefined {
  const where = `${area}[${index}]`;
  if (!isRecord(raw)) {
    problems.push(`${where} is not an object`);
    return undefined;
  }
  const name = typeof raw.name === 'string' ? raw.name : undefined;
  if (name === undefined || name === '') {
    problems.push(`${where} has no name`);
    return undefined;
  }

  const kind = typeof raw.kind === 'string' ? raw.kind : '';
  const load = typeof raw.load === 'string' ? raw.load : '';
  if (!(KINDS as readonly string[]).includes(kind)) {
    problems.push(`${name} has kind ${JSON.stringify(kind)}, expected one of ${KINDS.join(', ')}`);
  }
  if (!(LOADS as readonly string[]).includes(load)) {
    problems.push(`${name} has load ${JSON.stringify(load)}, expected one of ${LOADS.join(', ')}`);
  }

  const grain = stringArray(raw.grain);
  const partitionKeys = stringArray(raw.partitionKeys);
  const measurementBases = stringArray(raw.measurementBases);
  const writtenBy = stringArray(raw.writtenBy);
  const canonicalPublisher =
    typeof raw.canonicalPublisher === 'string' && raw.canonicalPublisher !== ''
      ? raw.canonicalPublisher
      : undefined;
  for (const [label, value] of [
    ['grain', grain],
    ['partitionKeys', partitionKeys],
    ['measurementBases', measurementBases],
    ['writtenBy', writtenBy],
  ] as const) {
    if (value === undefined) {
      problems.push(`${name}.${label} is not an array of strings`);
    }
  }
  if (canonicalPublisher === undefined) {
    problems.push(`${name}.canonicalPublisher is not a non-empty string`);
  }

  const rawColumns = raw.columns;
  if (!Array.isArray(rawColumns) || rawColumns.length === 0) {
    problems.push(`${name} declares no columns`);
    return undefined;
  }
  const columns = rawColumns
    .map((column, position) => readColumn(column, `${name}.columns[${position}]`, problems))
    .filter((column): column is GeneratedColumn => column !== undefined);

  if (grain === undefined || partitionKeys === undefined) {
    return undefined;
  }
  if (measurementBases === undefined || writtenBy === undefined) {
    return undefined;
  }
  if (canonicalPublisher === undefined) {
    return undefined;
  }

  const fieldIds = columns.map((column) => column.fieldId);
  if (new Set(fieldIds).size !== fieldIds.length) {
    problems.push(`${name} repeats a physical fieldId`);
  }
  for (const [position, column] of columns.entries()) {
    if (column.fieldId !== position + 1) {
      problems.push(
        `${name}.${column.name} has fieldId ${column.fieldId}, but Glue will assign ordinal ${position + 1}`,
      );
    }
  }

  const columnNames = new Set(columns.map((column) => column.name));

  // A partition key that is not a column produces an Iceberg partition spec referring to a
  // field id that does not exist. CloudFormation reports that as a generic Glue validation
  // failure minutes into a deploy, so it is worth catching by name here.
  for (const key of partitionKeys) {
    if (!columnNames.has(key)) {
      problems.push(`${name} partitions on ${key}, which is not one of its columns`);
    }
  }
  // Same for grain, one step less severe: it does not break the deploy, but a grain naming a
  // column the table does not have means the declared uniqueness cannot be checked at all.
  for (const key of grain) {
    if (!columnNames.has(key)) {
      problems.push(`${name} declares grain on ${key}, which is not one of its columns`);
    }
  }

  return {
    name,
    kind: kind as TableKind,
    load: load as LoadMode,
    grain,
    partitionKeys,
    measurementBases,
    writtenBy,
    canonicalPublisher,
    columns,
  };
}

/** Load the permanent Semantic V2 physical catalog. */
export function loadGeneratedV2Storage(filePath: string): GeneratedV2Storage {
  const artifact = 'contracts/generated/v2-tables.json';
  let parsed: unknown;
  try {
    parsed = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
  } catch (error) {
    throw new GeneratedSchemaError(
      `Could not read the generated V2 schema at ${filePath}: ${(error as Error).message}`,
    );
  }
  if (!isRecord(parsed) || parsed.version !== 1 || !isRecord(parsed.storage)) {
    fail(['the V2 file requires version 1 and a storage object'], artifact);
  }
  const storage = parsed.storage;
  const prefix = (name: string): string | undefined => {
    const value = storage[name];
    if (typeof value !== 'string') return undefined;
    const normalized = value.replace(/\/$/, '');
    const safe =
      normalized !== '' &&
      !normalized.startsWith('/') &&
      normalized.split('/').every((part) => /^[a-z0-9-]+$/.test(part));
    return safe ? normalized : undefined;
  };
  const sourceAlignedPrefix = prefix('sourceAlignedPrefix');
  const canonicalCandidatePrefix = prefix('canonicalCandidatePrefix');
  const canonicalCurrentPrefix = prefix('canonicalCurrentPrefix');
  const problems: string[] = [];
  const prefixes = [
    ['sourceAlignedPrefix', sourceAlignedPrefix],
    ['canonicalCandidatePrefix', canonicalCandidatePrefix],
    ['canonicalCurrentPrefix', canonicalCurrentPrefix],
  ] as const;
  for (const [name, value] of prefixes) {
    if (value === undefined) problems.push(`storage.${name} is not a safe relative prefix`);
  }
  const presentPrefixes = prefixes.flatMap(([, value]) => (value === undefined ? [] : [value]));
  if (new Set(presentPrefixes).size !== presentPrefixes.length) {
    problems.push('V2 storage prefixes must be distinct');
  }

  const readArea = (name: string, sourceMetadata = false): GeneratedTable[] => {
    const raw = parsed[name];
    if (!Array.isArray(raw)) {
      problems.push(`${name} is not a table array`);
      return [];
    }
    if (sourceMetadata) {
      for (const [index, value] of raw.entries()) {
        if (!isRecord(value)) continue;
        for (const field of ['contractId', 'dataset'] as const) {
          if (typeof value[field] !== 'string' || value[field] === '') {
            problems.push(`${name}[${index}].${field} is not a non-empty string`);
          }
        }
        if (!['fact', 'dimension', 'control_total'].includes(String(value.role))) {
          problems.push(`${name}[${index}].role is invalid`);
        }
        if (!['ready', 'blocked'].includes(String(value.readiness))) {
          problems.push(`${name}[${index}].readiness is invalid`);
        }
      }
    }
    const tables = raw
      .map((table, index) => readTable(table, index, problems, name))
      .filter((table): table is GeneratedTable => table !== undefined);
    const duplicates = tables
      .map((table) => table.name)
      .filter((value, index, all) => all.indexOf(value) !== index);
    for (const duplicate of new Set(duplicates)) problems.push(`${name}.${duplicate} repeats`);

    const constructIds = tables.map((table) =>
      table.name
        .split('_')
        .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
        .join(''),
    );
    for (const duplicate of new Set(
      constructIds.filter((value, index, all) => all.indexOf(value) !== index),
    )) {
      problems.push(`${name} has a normalized construct-id collision at ${duplicate}`);
    }
    return tables;
  };

  const sourceAlignedTables = readArea('sourceAlignedTables', true);
  const canonicalCandidateTables = readArea('canonicalCandidateTables');
  const canonicalCurrentTables = readArea('canonicalCurrentTables');
  if (sourceAlignedTables.length === 0) problems.push('no source-aligned tables are declared');
  if (canonicalCandidateTables.length === 0) problems.push('no candidate tables are declared');
  if (canonicalCurrentTables.length === 0) problems.push('no current tables are declared');

  const candidateByName = new Map(canonicalCandidateTables.map((table) => [table.name, table]));
  const currentByName = new Map(canonicalCurrentTables.map((table) => [table.name, table]));
  const canonicalNames = new Set([...candidateByName.keys(), ...currentByName.keys()]);
  for (const name of canonicalNames) {
    const candidate = candidateByName.get(name);
    const current = currentByName.get(name);
    if (candidate === undefined || current === undefined) {
      problems.push(`candidate/current canonical table sets differ at ${name}`);
    } else if (JSON.stringify(candidate) !== JSON.stringify(current)) {
      problems.push(`candidate/current canonical schemas differ at ${name}`);
    }
  }

  const locations = [
    ...sourceAlignedTables.map((table) => `${sourceAlignedPrefix}/${table.name}`),
    ...canonicalCandidateTables.map((table) => `${canonicalCandidatePrefix}/${table.name}`),
    ...canonicalCurrentTables.map((table) => `${canonicalCurrentPrefix}/${table.name}`),
  ];
  if (new Set(locations).size !== locations.length) {
    problems.push('V2 table projections contain a duplicate physical location');
  }
  if (problems.length > 0) fail(problems, artifact);

  return {
    version: 1,
    sourceAlignedPrefix: sourceAlignedPrefix!,
    canonicalCandidatePrefix: canonicalCandidatePrefix!,
    canonicalCurrentPrefix: canonicalCurrentPrefix!,
    sourceAlignedTables,
    canonicalCandidateTables,
    canonicalCurrentTables,
  };
}
